package com.dy.artisan3d.ui.screen.main.homeimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport com.dy.artisan3d.domain.repository.ArtisanMediaRepositoryimport com.dy.artisan3d.domain.repository.BrandRepositoryimport com.dy.artisan3d.domain.repository.CategoryRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.asyncimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass HomeViewModel(    private val repository: CategoryRepository,    private val brandRepository: BrandRepository,    private val artisanMediaRepository: ArtisanMediaRepository,    private val artisanArticleRepository: ArtisanArticleRepository,    private val appLang: AppLanguage) : ViewModel() {    private val _uiState = MutableStateFlow(HomeUiState())    val uiState = _uiState.asStateFlow()    init {        fetchHomeData()    }    fun fetchHomeData(isRefresh: Boolean = false) {        if (!isRefresh && _uiState.value.isInitialized) return        viewModelScope.launch {            _uiState.update { it.copy(isLoading = true) }            try {                // Parallel so'rovlar                val categoriesDeferred = async { repository.getCategories(appLang.current) }                val brandsDeferred = async { brandRepository.getBrands(appLang.current) }                val mediaDeferred = async { artisanMediaRepository.getMediaList(1, appLang.current) }                val articlesDeferred = async { artisanArticleRepository.getArticles(1, appLang.current) }                // .getOrThrow() - Agar birontasi xato bo'lsa, catch'ga sakraydi                val categories = categoriesDeferred.await().getOrThrow()                val brands = brandsDeferred.await().getOrThrow()                val media = mediaDeferred.await().getOrThrow()                val article = articlesDeferred.await().getOrThrow()                _uiState.update {                    it.copy(                        categories = categories,                        brands = brands,                        media = media,                        articles = article,                        isLoading = false,                        isInitialized = true,                        isError = false                    )                }            } catch (e: Exception) {                // Birontasi xato bersa, hammasi to'xtaydi va shu yer ishlaydi                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        errorRes = errorMsg,                        isInitialized = true                    )                }            }        }    }}